-- Vote2027 — notifications « Question du jour » (texte humoristique)
-- À exécuter après supabase/notifications_schema.sql. Idempotent : ne touche
-- pas aux notifications déjà envoyées.
-- Envoi à 10 h (heure de Paris), sauf le 16/10/2026 : 23 h 30.
-- ═════════════════════════════════════════════════════════════

delete from public.notifications_planning
 where categorie = 'question_du_jour' and envoye_le is null
   and date_envoi between '2026-10-16' and '2026-12-26';

